// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/blocks", wrapper.ListBlocks)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/blocks", wrapper.CreateBlock)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/blocks/{id}", wrapper.DeleteBlock)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/blocks/{id}", wrapper.GetBlock)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/blocks/{id}", wrapper.UpdateBlock)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/blocks/import", wrapper.ImportBlocks)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/blocks/export", wrapper.ExportBlocks)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/generate", wrapper.GenerateSchedule)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/apply", wrapper.ApplySchedule)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/schedule", wrapper.GetSchedule)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/history", wrapper.GetHistory)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/applies", wrapper.ListApplyRuns)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/state/series", wrapper.ListSeriesState)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/state/series/{show_title}", wrapper.PatchSeriesState)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/channels", wrapper.ListChannels)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/status", wrapper.GetStatus)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/media/shows", wrapper.ListMediaShows)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/media/meta", wrapper.GetMediaMeta)
	})

	return r
}

